public static void syncFile(File file) {
    try (FileOutputStream fos = new FileOutputStream(file, true)) {
        fos.getFD().sync();
    } catch (Exception e) {
        e.printStackTrace();
    }
}

public static void syncDir(File dir) {
    if (dir == null || !dir.exists()) return;

    if (dir.isFile()) {
        syncFile(dir);
        return;
    }

    File[] files = dir.listFiles();
    if (files != null) {
        for (File f : files) {
            syncDir(f);
        }
    }
}

